    content: `**חסיון הליך הגישור**

**כללי**

על הליך הגישור חל חסיון. החסיון חל לא רק על הנאמר באופן אישי בין צד לבין המגשר בשיחות אישיות, אלא חל אף על כל הנאמר בתהליך — הן על ידי הצדדים בהיותם מתדיינים ביניהם לבין עצמם, והן יחד עם המגשר במסגרת הליך הגישור.

פירוש המילה חסיון הוא: מעטה סודיות, שמירת סודיות. קיימים כמה סוגי חסיון מקצועיים המורים על שמירת סודיות של מידע: חסיון עיתונאי, חסיון עורך דין-לקוח, חסיון בנק-לקוח, חסיון רפואי, וחסיון מפני הפללה עצמית.

הרציונל העומד מאחורי החסיון החל על הליך גישור גירושין נועד במטרה לאפשר לצדדים לנהל ביניהם משא-ומתן חופשי. דבר זה אפשרי רק כאשר לצדדים אין חשש שמא דברים שיאמרו במסגרת הגישור ישמשו לרעה כנגדם בעתיד. ללא חסיון, הצדדים יהיו מנועים מלמסור פרטים כלשהם באשר להליך הגישור, מחשש שלבסוף לא יצלח הגישור והעניין ידון בערכאות.

אולם ביודעם שהליך הגישור הוא חסוי בפני כל גורם משפטי, כולל בית המשפט, ושאף משפט שנאמר במסגרת ההליך לא ישמש לרעה כנגדם — הצדדים ירשו לעצמם לנהל מו"מ חופשי סביב האינטרסים שלהם, מבלי להחביאם מאחורי עמדות קשוחות. עיקרון זה מהווה סיכוי גבוה לפתרון ויישוב הסכסוך בין הצדדים.

**מקורות החסיון בהליך הגישור**

גישור הוא הליך בו מתקיים ניהול משא-ומתן, שמטרתו למצוא פתרונות וליישב את כל המחלוקות הנדונות במסגרתו, על ידי גיבוש וחתימת הסכם גישור המקובל הדדית על הצדדים.

כפי שנאמר בהקשר זה מפי כבוד נשיא (דאז) בית המשפט העליון, השופט שמגר: "ההנחה היא, כי כאשר מתנהל משא ומתן לשם השגת פשרה, הצדדים לו עלולים להימנע ממצגים, הצהרות או הצעות, אשר טמון בחובם ויתור כלשהו לטובת הצד השני, מחשש שויתור כאמור ישמש כראיה לרעתם בהליך עתידי. בכך עלולים הסיכויים להשגת פשרה בין הצדדים להיפגע, ותוצאה בלתי רצויה זו בא הכלל, המגביל את קבילותם של מסמכים אלו, למנוע."

כמו כן, יפים הם דבריו של כבוד השופט יפרח לעניין זה: "כל שהוחלף במסגרת הליך הגישור, בין בעלי הדין לבין עצמם וביניהם לבין המגשר, בין בעל-פה ובין בכתב, חסוי הוא וחסין מגילוי — וליתר דיוק: אסור בגילוי."

ובפסק דין אחר, ציינה כבוד השופטת שטופמן, בתיק שהתייחס באופן ספציפי לנושא של גישור גירושין: "הליך הגישור מבוסס, בין היתר, על עקרון ההפרדה בין הליך הגישור להליך המתנהל בבית המשפט לענייני משפחה, וזאת על מנת לאפשר לצדדים לחלוק בפתיחות את המידע שנועד לקדם את המשא ומתן בין הצדדים, גם אם אין ברצונם או בכוונתם להביא מידע זה בפני בית המשפט."

החוק קובע כך: "דברים שנמסרו במסגרת הליך גישור לא ישמשו ראיה בהליך משפטי אזרחי." ובמקום אחר: "בעלי הדין מתחייבים לא למסור לבית המשפט דברים שנאמרו בהליך הגישור ולא להציג מסמכים בכל עניין שהועלה, במישרין או בעקיפין, בהליך הגישור."

**החסיון חל גם על המגשר**

חשוב לציין כי החסיון אינו חל רק על הצדדים עצמם, אלא חל גם על המגשר עצמו. לעניין זה, התקנות קובעות: "המגשר לא ישתמש בכל מידע שנמסר לו במהלך הגישור לכל מטרה זולת הגישור. המגשר לא יגלה כל מידע שנמסר לו במהלך הגישור למי שאינו צד לגישור. מסר בעל דין מידע למגשר תוך דרישה לשומרו בסוד, ישמור המגשר על סודיות המידע כלפי כל בעל דין אחר, אלא אם כן ויתר מוסר המידע על הסודיות."

כמו כן, לשמירה על עקרון החסיון נקבע: "בעלי הדין מתחייבים לא להזמין את המגשר למסור עדות, בין בכתב בין בעל-פה, או להציג מסמכים בכל עניין שהועלה, במישרין או בעקיפין, בהליך הגישור."

**האם החסיון מוחלט?**

השופטים מכירים בחשיבותו של החסיון החל בהליכי גישור. לפיכך, אך ורק במקרים מאוד חריגים וקיצוניים ייעתרו השופטים לבקשת צד להסרת החסיון — כגון במקרה שאחד הצדדים פעל בחוסר תום-לב ובמזיד, כדי לנצל את קיום הליך הגישור להשגת יתרונות פסולים.

**לסיכום**

החסיון חל על כל הדברים שהוחלפו בהליך גישור, לרבות מסמכים, ללא יוצא מן הכלל. הצדדים אינם רשאים למסור לאף צד שלישי — לרבות במסגרת הליכים בבית משפט — מידע, פרטים, או מסמכים שהוחלפו ביניהם במסגרת הגישור. המגשר עצמו גם אינו רשאי לגלות מידע שנמסר לו על ידי הצדדים במהלך הגישור. כמו כן, לא ניתן לזמן את המגשר לעדות בבית המשפט לגבי מידע שנמסר לו. יתר על כן, המגשר מחויב בסודיות גם לגבי מידע שנמסר לו באופן אישי ובנפרד על ידי מי מהצדדים, אלא אם כן אותו צד ויתר על כך. גם בתי המשפט מחויבים לשמירת החסיון, ורק במקרים קיצוניים יעתרו לבקשת צד להסרתו.`,
    excerpt: `על הליך הגישור חל חסיון מלא. החסיון חל על כל הנאמר בתהליך — הן על ידי הצדדים ביניהם לבין עצמם, והן יחד עם המגשר. מטרתו לאפשר לצדדים לנהל משא-ומתן חופשי ללא חשש שדבריהם ישמשו כנגדם בעתיד...`,
