    title: `גישור ככלי טיפולי בישוב סכסוכים בין בני זוג`,
    content: `**גישור ככלי טיפולי בישוב סכסוכים בין בני זוג**

**על הגישור הזוגי**

גישור הוא כלי המשמש לישוב סכסוכים, שיכול להוות כלי טיפולי אפקטיבי לטיפול במשבר ספציפי מוגדר גבולות, הנוצר בין בני זוג.

כלי משמעותי זה מיועד לבני זוג נשואים שנמצאים במשבר זוגי הנובע מסכסוך ידוע ומוגדר לצדדים והמהוה נקודת המחלוקת ביניהם. משליך על יחסי הזוגיות בניהם וגורם להם קשיים בתקשורת המונעים את יישוב הסכסוך באופן ענייני. גישור זוגי מציע דרך ליציאה מהמבוי הסתום בו נמצאים הצדדים, על ידי פתרון נקודות המחלוקת, וזאת באמצעות כלים הנלמדים מעולם הגישור.

בגישה זו, אין המגשר מתיימר לטפל בבני הזוג עצמם, או במשקעים שנוצרו במשך הנישואים אצל כל אחד מהצדדים ובתא הנישואין כיחידה משותפת. המגשר מתמקד בנקודות המחלוקת בין בני הזוג המוגדרות וידועות להם או שיתבררו תוך כדי תהליך הגישור. ככול שמתיישב הסכסוך בין הצדדים, רמת המתח הזוגית יורדת והיכולת לתקשר באופן חיובי עולה.

גישור זוגי מתמקד ושם על השולחן הדיונים את מהות הסכסוך, נקודות המחלוקת ואי ההסכמה והאופנים בהם הם באים לידי ביטוי. זאת במטרה ראשונה במעלה לייצר הסכמות ופתרונות. באופן זה, יוצר תהליך הגישור, דיונים קוגניטיביים אופרטיביים ויצירתיים בין בני הזוג, ממוקדי מטרות ופתרונות, מה שיוצר באופן עקיף תקשורת בין בני הזוג באופן נטול אמוציות, משקעים ואשמות ככל שניתן.

**עקרונות וכלים בהם משתמש המגשר בהליך הגישור:**

1. **אובייקטיביות** — הפרדת האנשים המעורבים מהבעיה
2. **התרכזות בדברי הצד הדובר** ולמידת האינטרסים שלו, לא בעמדותיו
3. **ניהול ושליטה ברגשות**
4. **הבעת אמפתיה**
5. **עריכת המסרים** של הצדדים באופן חיובי
6. **הימנעות ממעגל של פעולה ותגובה** — בחינת הכוחות המנהלים את התהליך
7. **הצבת יעדים אופטימליים** ומטרות אידאליות לסיום הסכסוך
8. **חתירה לפתרון** ששני הצדדים יהיו מרוצים ממנו

הרציונל אומר, ככול שתגדל ההצלחה סביב מציאת פתרונות לנקודות הסכסוך, ירדו המתחים והכעסים, דבר המהוה בסיס, התכנות וסיכוי ליצירת קשר חיובי בניהם ולהמשיך החיים המשותפים יחדיו. לחילופין, במידת הצורך, כאשר אין ברצון הצדדים להמשיך את הנישואין, ישוב הסכסוכים ושיפור היחסים והתקשורת בניהם, יסייעו להם להגיע להסכמים אחרים המקובלים עליהם, ויוכלו להיפרד זה מזו באופן מכובד.

**המגשר הזוגי**

גישור זוגי מתבצע על ידי מגשר בעל אוריינטציה טיפולית. המגשר הזוגי הוא גורם אובייקטיבי, צד שלישי, שנמצא מחוץ למחלוקות שתפקידו להנחות את הזוג להגיע בכוחות עצמם לפתרונות. יש לו יכולות, ניסיון, וכישורים לגרום לצדדים להגיע להחלטות ולקיים שיח בקשר לעתידם המשותף בהמשך הנישואין או לחילופין בהגיעם להסכם מקובל בנושאי המחלוקת שביניהם בגירושין.

היתרון שלו על מטפל בתהליך זוגי הוא, שאינו מטפל בבני הזוג. הוא לא מתנהל עם הזוג בנושאים רגשיים עמוקים, דבר המונע אשמות הדדיות. התהליך הוא הגיוני וניטרלי.

בעזרתו של המגשר הזוגי, קל יותר לצדדים להבין אחד את הצד השני, מאחר ואינם עוסקים באופן מוצהר ברגשות שליליים הנובעים מקיום הקשר, באשמות הדדיות, באפשור או שלילה של המשך הקשר, אלא ממוקדים סביב פתרון הבעיות המוגדרות.`,
