    title: `אבני דרך בהליך הגישור`,
    content: `**אבני דרך בהליך הגישור**

*מאת: מאיר שמעון עשור*

מאמר זה מביא שש עצות שהן בבחינת לחם חוקם של מגשרים ותיקים, ואבני דרך מועילות עבור מגשרים צעירים בראשית דרכם.

ספרם של רוג'ר פישר וויליאם יורי שהיה מהפכני לזמנו, דוגל באפשרות של פתרון סכסוכים המניב רווח הדדי עבור שני הצדדים. לשיטתם פתרון סכסוך או מהלכו של משא ומתן אינם צריכים להיות תחרותיים ונשלטים על ידי יחסי ניצחון-כישלון, רווח הפסד או ויתור על מנת להימנע מסכסוך, אלא להשגת פתרון לסכסוך או תוצאת משא ומתן בעלי ערך מוסף על זה שהתכוונו לו בתחילתו של ההליך.

**שש העצות:**

**1. הפרד את האנשים המעורבים מהבעיה**

במהלך הסכסוך או אף במשך הליך הגישור, הצדדים הנתונים בכאבם ובכעסם, נוטים לשכוח שגם לצד האחר ישנן רגשות, דעות, ערכים ורקע, שייחודיים לו ונמצאים ברקע דבריו או מעשיו. כאשר אי-הבנות ועימותים מתעוררים במהלך הגישור, שומה על המגשר לסייע לצדדים בזיהוי והבנת הבעיה והבנת ההקשר שלה ביחס לצדדים המעורבים בגישור.

**2. התרכז באינטרסים ולא בעמדות**

תהליך הגישור למעשה נפתח בשלב הראשון בהצגת העמדות של כל צד. תפקידו של המגשר לחשוף את האינטרסים העומדים מאחורי עמדות הצדדים. הכלי במקרה זה יהיה בירור עם אותו צד, באמצעות שאלות פתוחות מה עומד בבסיס העמדה שהצהיר עליה.

**3. למד לנהל ולשלוט ברגשות**

על המגשר להיות ער לא רק לאינטרסים שביסוד עמדות הצדדים, אלא גם לרגשות הקשורים באותם אינטרסים. תפקידו של המגשר לפעול על מנת שיינתן מקום לאותם רגשות בתהליך הגישור, כך שכל צד יוכל ללא היסוס לבטא רגשות שמשפיעים עליו.

**4. הבעת אמפתיה**

קיימת חשיבות רבה להבעת אמפתיה מצד המגשר לצדדים באופן שווה. אמפתיה תועיל בתהליך בפריצת מחסומים, סילוק התנגדויות והתגברות על מבוי סתום. כל אדם מוקיר הבעות הבנה והכרה ברגשות שלו.

**5. ערוך באופן חיובי את המסרים של הצדדים ושלך**

תקשורת בנימה חיובית הינה הדרך היעילה ביותר להביא צדדים לידי הסכמות. הטחת האשמות וביקורת מן הסתם תשיג את התוצאות ההפוכות. כאשר המגשר משקף טענות צד אחד, יעשה זאת בנועם ובנימה חיובית, ידבר על האינטרסים העומדים מאחורי העמדה, ללא הבעת הזדהות או נקיטת עמדה.

**6. הימנע מהמעגל של פעולה ותגובה**

במצב בו מופנית ביקורת נוקבת, על המגשר להיזהר מליפול במלכודת השכיחה של פעולה ותגובה. המגשר חייב להפגין את כישוריו, בכך שיימנע מהחמרת המצב ויסרב להגיב לפרובוקציה. במצב זה טוב יעשה המגשר אם יתעל את הביקורת וההתנגדות לקידום אקטיבי יותר של ההליך.`,
    excerpt: `מאמר זה מביא שש עצות שהן בבחינת לחם חוקם של מגשרים ותיקים, ואבני דרך מועילות עבור מגשרים צעירים בראשית דרכם — מהפרדת אנשים מבעיות, דרך ניהול רגשות ועד הבעת אמפתיה.`,
